from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 1

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
    ) -> int:
        if end <= start:
            raise ValueError("Appointment end must be after its start")
        if start < now:
            raise ValueError("Appointment cannot start in the past")

        for appointment in self._appointments.values():
            if (
                not appointment["cancelled"]
                and appointment["patient"] == patient
                and appointment["start"] >= now
            ):
                raise ValueError("Patient already has an upcoming appointment")

        if not self.is_free(doctor, start, end):
            raise ValueError("Doctor is not available")

        appointment_id = self._next_id
        self._next_id += 1
        self._appointments[appointment_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
            "blocked": True,
        }
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        appointment = self._appointments[appointment_id]
        if appointment["cancelled"]:
            return

        appointment["cancelled"] = True
        if appointment["start"] - now >= timedelta(hours=24):
            appointment["blocked"] = False

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        if end <= start:
            raise ValueError("Appointment end must be after its start")

        return not any(
            appointment["blocked"]
            and appointment["doctor"] == doctor
            and start < appointment["end"]
            and appointment["start"] < end
            for appointment in self._appointments.values()
        )
```

